            aWandererH = aWandererH + (((RotL64(aCross, 41U) + RotL64(aOrbiterA, 14U)) + aOrbiterH) + RotL64(aCarry, 5U));
            aWandererD = aWandererD ^ (((RotL64(aScatter, 27U) + aOrbiterK) + RotL64(aOrbiterD, 21U)) + aTwistWandererUpdateSaltC[(((255U - aIndex) + 255U)) & S_SALT1]);
